def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Gather opponent and own action lists
    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Cumulative counts
    c_opp = opp.count('C')
    d_opp = n - c_opp

    # Immediate simple opponents
    if d_opp == 0:
        # Opponent always cooperates: exploit near end, otherwise cooperate
        if n >= 95:
            return 'D'
        return 'C'
    if c_opp == 0:
        return 'D'

    # Current streaks
    streak_d = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and opp[i] == 'C':
        streak_c += 1
        i -= 1

    coop_rate = c_opp / n
    last_opp = opp[n - 1]
    last_me = me[n - 1]

    # Endgame: defect hard when we can
    remaining = 100 - n
    if remaining <= 6:
        if streak_d == 0 and coop_rate > 0.5:
            return 'D'
        if coop_rate > 0.7:
            return 'D'
        return 'C' if streak_c >= 1 else 'D'

    # Strong punishment for ongoing defection streaks
    if streak_d >= 2:
        # But forgive if cooperation rate incredibly high and no long streak
        if coop_rate > 0.9 and streak_d == 2 and n > 20:
            return 'C'
        return 'D'

    # Opponent defected last round only
    if streak_d == 1:
        # Be forgiving if history is broadly cooperative
        if coop_rate > 0.75 and streak_c >= 3:
            return 'C'
        if n >= 4 and opp[n - 2] == 'C' and opp[n - 3] == 'C':
            return 'C'
        # If we also defected last, they may be retaliating; return to C
        if last_me == 'D':
            return 'C'
        return 'D'

    # Now opponent cooperated last (streak_d == 0)
    # Detect mirroring (TFT-like) opponents
    if n >= 4:
        mirror = 0
        for i in range(1, n):
            if opp[i] == me[i - 1]:
                mirror += 1
        if mirror >= (n - 1) * 0.75:
            # Mirror their action: play what they just played (i.e., their last)
            return last_opp

    # Detect alternating pattern
    if n >= 6:
        alt = 0
        for i in range(1, n):
            if opp[i] != opp[i - 1]:
                alt += 1
        if alt >= n - 2:
            if last_opp == 'C':
                return 'D'
            return 'C'

    # Highly cooperative opponent: cooperate, but probe rarely
    if coop_rate >= 0.85:
        if n > 25 and n % 21 == 0 and streak_c >= 3:
            return 'D'
        return 'C'

    # Moderately cooperative opponent
    if coop_rate >= 0.6:
        # Occasional probe to test exploitability
        if streak_c >= 2 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Low cooperation: defect more, but mix in cooperation to test
    if coop_rate >= 0.4:
        if last_opp == 'C':
            # They cooperated; exploit a bit
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        return 'D'

    # Opponent mostly defects
    return 'D'
